CREATE TABLE public.provider_organisations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.provider_organisations TO authenticated; GRANT ALL ON public.provider_organisations TO service_role; ALTER TABLE public.provider_organisations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.organisation_members(organisation_id uuid NOT NULL REFERENCES public.provider_organisations(id),user_id uuid NOT NULL,member_role text NOT NULL DEFAULT 'member' CHECK(member_role IN('owner','member')),PRIMARY KEY(organisation_id,user_id));
GRANT SELECT ON public.organisation_members TO authenticated; GRANT ALL ON public.organisation_members TO service_role; ALTER TABLE public.organisation_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.organisation_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organisation_id uuid NOT NULL REFERENCES public.provider_organisations(id),email text NOT NULL,token_hash text NOT NULL UNIQUE,created_by uuid NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',accepted_at timestamptz);
GRANT ALL ON public.organisation_invites TO service_role; ALTER TABLE public.organisation_invites ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.profiles ADD COLUMN organisation_id uuid REFERENCES public.provider_organisations(id);
INSERT INTO public.provider_organisations(id,name) SELECT id,organisation_name FROM public.profiles;
INSERT INTO public.organisation_members SELECT id,id,'owner' FROM public.profiles;
UPDATE public.profiles SET organisation_id=id;
ALTER TABLE public.scholarships ADD COLUMN organisation_id uuid REFERENCES public.provider_organisations(id),ADD COLUMN maximum_award_value integer;
ALTER TABLE public.scholarships DISABLE TRIGGER scholarship_version_before; ALTER TABLE public.scholarships DISABLE TRIGGER scholarship_version_after;
UPDATE public.scholarships SET organisation_id=provider_id,maximum_award_value=stipend_aud;
ALTER TABLE public.scholarships ENABLE TRIGGER scholarship_version_before; ALTER TABLE public.scholarships ENABLE TRIGGER scholarship_version_after;
COMMENT ON COLUMN public.scholarships.stipend_aud IS 'DEPRECATED: replaced by maximum_award_value';
ALTER TABLE public.matches ADD COLUMN fund_id uuid REFERENCES public.scholarships(id),ADD COLUMN rule_version integer,ADD COLUMN organisation_id uuid REFERENCES public.provider_organisations(id);
UPDATE public.matches SET organisation_id=provider_id;
ALTER TABLE public.student_eligibility ADD COLUMN gender text,ADD COLUMN degree_level text,ADD COLUMN first_undergraduate_degree boolean,ADD COLUMN years_completed numeric,ADD COLUMN campus_state text;
CREATE TABLE public.australian_universities(name text PRIMARY KEY);
GRANT SELECT ON public.australian_universities TO authenticated; GRANT ALL ON public.australian_universities TO service_role; ALTER TABLE public.australian_universities ENABLE ROW LEVEL SECURITY;
CREATE POLICY university_read ON public.australian_universities FOR SELECT TO authenticated USING(true);
CREATE FUNCTION public.is_organisation_member(p_org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.organisation_members WHERE organisation_id=p_org AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_organisation_member(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.is_organisation_member(uuid) TO authenticated;
CREATE POLICY organisation_read ON public.provider_organisations FOR SELECT TO authenticated USING(public.is_organisation_member(id));
CREATE POLICY member_read ON public.organisation_members FOR SELECT TO authenticated USING(public.is_organisation_member(organisation_id));
CREATE POLICY org_fund_read ON public.scholarships FOR SELECT TO authenticated USING(public.is_organisation_member(organisation_id));
CREATE POLICY org_match_read ON public.matches FOR SELECT TO authenticated USING(public.is_organisation_member(organisation_id));
CREATE POLICY org_version_read ON public.scholarship_rule_versions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.scholarships s WHERE s.id=fund_id AND public.is_organisation_member(s.organisation_id)));
CREATE POLICY org_legacy_audit_read ON public.scholarship_audit FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.scholarships s WHERE s.id=fund_id AND public.is_organisation_member(s.organisation_id)));
CREATE POLICY org_identity_accepted ON public.student_identities FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.matches m WHERE m.student_id=student_identities.student_id AND m.status='accepted' AND public.is_organisation_member(m.organisation_id)));
CREATE POLICY org_private_deed_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='trust-deeds' AND EXISTS(SELECT 1 FROM public.scholarships s WHERE s.deed_path=name AND public.is_organisation_member(s.organisation_id)));
REVOKE UPDATE ON public.profiles FROM authenticated;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
INSERT INTO public.provider_organisations(id,name) VALUES(new.id,coalesce(new.raw_user_meta_data->>'organisation_name',''));
INSERT INTO public.organisation_members VALUES(new.id,new.id,'owner');
INSERT INTO public.profiles(id,organisation_name,contact_person,organisation_id) VALUES(new.id,coalesce(new.raw_user_meta_data->>'organisation_name',''),coalesce(new.raw_user_meta_data->>'contact_person',''),new.id);
INSERT INTO public.provider_credits(provider_id,balance) VALUES(new.id,12); RETURN new; END $$;
CREATE FUNCTION public.create_organisation_invite(p_email text,p_hash text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_org uuid; BEGIN
SELECT organisation_id INTO v_org FROM public.profiles WHERE id=auth.uid();
IF NOT EXISTS(SELECT 1 FROM public.organisation_members WHERE organisation_id=v_org AND user_id=auth.uid() AND member_role='owner') THEN RAISE EXCEPTION 'Only organisation owners can invite team members'; END IF;
IF p_hash !~ '^[a-f0-9]{64}$' OR p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Invalid invitation'; END IF;
INSERT INTO public.organisation_invites(organisation_id,email,token_hash,created_by) VALUES(v_org,lower(trim(p_email)),p_hash,auth.uid()); END $$;
CREATE FUNCTION public.accept_organisation_invite(p_token text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_inv public.organisation_invites; v_email text; BEGIN
SELECT lower(email) INTO v_email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL;
SELECT * INTO v_inv FROM public.organisation_invites WHERE token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') AND email=v_email AND expires_at>now() AND accepted_at IS NULL FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'Invitation invalid, expired, or for a different verified email'; END IF;
INSERT INTO public.organisation_members VALUES(v_inv.organisation_id,auth.uid(),'member') ON CONFLICT DO NOTHING;
UPDATE public.profiles SET organisation_id=v_inv.organisation_id WHERE id=auth.uid(); UPDATE public.organisation_invites SET accepted_at=now() WHERE id=v_inv.id; END $$;
REVOKE ALL ON FUNCTION public.create_organisation_invite(text,text),public.accept_organisation_invite(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_organisation_invite(text,text),public.accept_organisation_invite(text) TO authenticated;
CREATE TABLE public.audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_type text NOT NULL CHECK(event_type IN('matched','unlock requested','accepted','declined','rule changed','rule attested')),actor text NOT NULL,actor_role text NOT NULL CHECK(actor_role IN('owner','member','student','system')),organisation_id uuid NOT NULL REFERENCES public.provider_organisations(id),fund_id uuid REFERENCES public.scholarships(id),rule_version integer,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_events TO authenticated; GRANT SELECT,INSERT ON public.audit_events TO service_role; ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_audit_read ON public.audit_events FOR SELECT TO authenticated USING(public.is_organisation_member(organisation_id));
CREATE TRIGGER immutable_events BEFORE UPDATE OR DELETE ON public.audit_events FOR EACH ROW EXECUTE FUNCTION public.prevent_fund_history_changes();
CREATE TRIGGER immutable_events_truncate BEFORE TRUNCATE ON public.audit_events FOR EACH STATEMENT EXECUTE FUNCTION public.prevent_fund_history_changes();
CREATE TRIGGER immutable_versions_truncate BEFORE TRUNCATE ON public.scholarship_rule_versions FOR EACH STATEMENT EXECUTE FUNCTION public.prevent_fund_history_changes();